'use client';

import * as React from 'react';
import {
  Brain,
  Cpu,
  Database,
  LayoutDashboard,
  PenTool,
  Settings,
  Sparkles,
  TrendingUp,
} from 'lucide-react';

import Link from "next/link";
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { generateStrategy, type StrategyRequest } from '@/lib/api';

export default function ViralytiqDashboardPage() {
  const [topic, setTopic] = React.useState(
    'Cutting pgvector RAG P95 latency under 200ms with Groq Llama 3.3'
  );

  const [pillar, setPillar] =
    React.useState<StrategyRequest['pillar']>(
      'Technical Deep-Dive'
    );

  const [loading, setLoading] = React.useState(false);

  const [draft, setDraft] = React.useState({
    hook:
      'Everyone talks about LLM reasoning.\nAlmost nobody measures retrieval tail latency.',

    body:
      'Three architectural changes brought our P95 RAG latency to 184ms using pgvector HNSW and Groq.',

    cta:
      'Where is the hidden latency hiding in your AI stack right now?',

    viralityScore: 94,
  });

  const handleRun = async (
    e: React.FormEvent
  ) => {
    e.preventDefault();

    setLoading(true);

    try {
      const data = await generateStrategy({
        topic,
        pillar,
        format: 'Text + Hook',
        tone: 'Direct & Analytical',
        targetAudience:
          'Seed-Series B SaaS Founders & Staff Engineers',
        useVoiceRag: true,
      });

      setDraft(data.post);
    } catch {
      setDraft({
        hook:
          'Most teams over-engineer retrieval.\nThe real edge is speed.',

        body:
          'Optimized RAG architectures consistently outperform larger models with poor retrieval.',

        cta:
          'What bottleneck surprised you most in production?',

        viralityScore: 89,
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-[#050816] text-white">

      {/* Sidebar */}
      <aside className="hidden md:flex w-72 glass-sidebar flex-col justify-between p-6">

        <div>
          <div className="mb-10">
            <h1 className="text-2xl font-bold">
              Viralytiq
            </h1>

            <p className="text-slate-400 text-sm mt-1">
              AI Content Strategist
            </p>
          </div>

          <nav className="space-y-2">

            <Link
              href="/dashboard"
              className="flex items-center gap-3 rounded-xl bg-indigo-500/20 border border-indigo-500/20 px-4 py-3"
            >
              <LayoutDashboard size={18} />
              <span>Overview</span>
            </Link>

            <Link
              href="/content"
              className="flex items-center gap-3 rounded-xl px-4 py-3 text-slate-400 hover:bg-white/5"
            >
              <PenTool size={18} />
              <span>Content Studio</span>
            </Link>

            <Link
              href="/memory"
              className="flex items-center gap-3 rounded-xl px-4 py-3 text-slate-400 hover:bg-white/5"
            >
              <Brain size={18} />
              <span>Brand Memory</span>
            </Link>

            <Link
              href="/analytics"
              className="flex items-center gap-3 rounded-xl px-4 py-3 text-slate-400 hover:bg-white/5"
            >
              <TrendingUp size={18} />
              <span>Analytics</span>
            </Link>

            <Link
              href="/traces"
              className="flex items-center gap-3 rounded-xl px-4 py-3 text-slate-400 hover:bg-white/5"
            >
              <Cpu size={18} />
              <span>Agent Traces</span>
            </Link>

            <Link
              href="/settings"
              className="flex items-center gap-3 rounded-xl px-4 py-3 text-slate-400 hover:bg-white/5"
            >
              <Settings size={18} />
              <span>Settings</span>
            </Link>

          </nav>
        </div>

        <div className="text-xs text-slate-500">
          FastAPI • LangGraph • Groq • pgvector
        </div>

      </aside>

      {/* Main */}
      <main className="flex-1 p-8 max-w-7xl mx-auto w-full">

        {/* Header */}

        <div className="mb-8">
          <h1 className="text-4xl font-bold">
            AI Content Strategy Studio
          </h1>

          <p className="text-slate-400 mt-2">
            Create high-performing LinkedIn content powered by
            Agents, RAG, LangGraph and Groq.
          </p>
        </div>

        {/* KPI Cards */}

        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-5 mb-8">

          <Card>
            <p className="text-slate-400 text-sm">
              Brand Score
            </p>

            <h3 className="text-4xl mt-2 font-bold">
              92
            </h3>
          </Card>

          <Card>
            <p className="text-slate-400 text-sm">
              Virality Score
            </p>

            <h3 className="text-4xl mt-2 font-bold text-indigo-300">
              {draft.viralityScore}
            </h3>
          </Card>

          <Card>
            <p className="text-slate-400 text-sm">
              Knowledge Chunks
            </p>

            <h3 className="text-4xl mt-2 font-bold">
              1432
            </h3>
          </Card>

          <Card>
            <p className="text-slate-400 text-sm">
              AI Confidence
            </p>

            <h3 className="text-4xl mt-2 font-bold text-green-400">
              97%
            </h3>
          </Card>

        </div>

        {/* Main Section */}

        <div className="grid lg:grid-cols-2 gap-6">

          {/* Generator */}

          <Card>

            <h2 className="text-xl font-semibold mb-5">
              Content Generator
            </h2>

            <form
              onSubmit={handleRun}
              className="space-y-5"
            >

              <div>
                <label className="block text-sm mb-2 text-slate-300">
                  Topic
                </label>

                <input
                  value={topic}
                  onChange={(e) =>
                    setTopic(e.target.value)
                  }
                  className="w-full rounded-xl border border-white/10 bg-white/5 px-4 py-3"
                />
              </div>

              <div>
                <label className="block text-sm mb-2 text-slate-300">
                  Content Pillar
                </label>

                <select
                  value={pillar}
                  onChange={(e) =>
                    setPillar(
                      e.target.value as StrategyRequest['pillar']
                    )
                  }
                  className="w-full rounded-xl border border-white/10 bg-white/5 px-4 py-3"
                >
                  <option>
                    Technical Deep-Dive
                  </option>
                  <option>
                    Founder Lessons
                  </option>
                  <option>
                    Contrarian Take
                  </option>
                  <option>
                    Product Breakdown
                  </option>
                </select>
              </div>

              <Button
                type="submit"
                disabled={loading}
              >
                <Sparkles className="h-4 w-4" />

                {loading
                  ? 'Generating...'
                  : 'Generate Strategy'}
              </Button>

            </form>

          </Card>

          {/* Preview */}

          <Card>

            <h2 className="text-xl font-semibold mb-5">
              LinkedIn Draft Preview
            </h2>

            <p className="text-xl font-bold whitespace-pre-line">
              {draft.hook}
            </p>

            <p className="text-slate-300 mt-6 leading-8 whitespace-pre-line">
              {draft.body}
            </p>

            <p className="text-indigo-300 mt-6 font-semibold">
              {draft.cta}
            </p>

          </Card>

        </div>

        {/* Agent Trace */}

        <Card className="mt-8">

          <h2 className="text-xl font-semibold mb-6">
            Agent Execution Trace
          </h2>

          <div className="grid md:grid-cols-2 gap-5">

            <div className="flex justify-between p-4 rounded-xl bg-white/5">
              <span>Research Agent</span>
              <span className="text-green-400">
                ✅ 1.2s
              </span>
            </div>

            <div className="flex justify-between p-4 rounded-xl bg-white/5">
              <span>Brand Agent</span>
              <span className="text-green-400">
                ✅ 0.8s
              </span>
            </div>

            <div className="flex justify-between p-4 rounded-xl bg-white/5">
              <span>Writing Agent</span>
              <span className="text-green-400">
                ✅ 2.1s
              </span>
            </div>

            <div className="flex justify-between p-4 rounded-xl bg-white/5">
              <span>Reviewer Agent</span>
              <span className="text-green-400">
                ✅ 0.7s
              </span>
            </div>

          </div>

        </Card>

      </main>
    </div>
  );
}